from typing import List

def minDifference(nums: List[int]):
    # 預處理每個 -1 的合法範圍 [L, R]
    n = len(nums)
    limits = []
    for i in range(n):
        if nums[i] == -1:
            l, r = float('-inf'), float('inf')
            if i > 0 and nums[i-1] != -1:
                l = max(l, nums[i-1] - k_dummy := 0) # 這裡邏輯在 check 內處理
            # 此處簡化思考：我們只需要在 check 時動態推導範圍
            limits.append(None)
        else:
            limits.append((nums[i], nums[i]))

    def check(k):
        # 用來儲存每個位置可能的取值範圍 [low, high]
        # 因為我們只能選兩個數 x, y，這意味著所有 -1 最終必須落在某個區間內
        # 或者說，所有的 -1 必須能被填入且與鄰居的差 <= k

        # 第一步：根據現有的數字推導每個位置的限制範圍
        lows = [float('-inf')] * n
        highs = [float('inf')] * n

        for i in range(n):
            if nums[i] != -1:
                lows[i] = highs[i] = nums[i]

        # 向右擴散限制
        for i in range(1, n):
            if nums[i-1] != -1:
                lows[i] = max(lows[i], lows[i-1] - k)
                highs[i] = min(highs[i], highs[i-1] + k)
            elif i > 0 and nums[i-1] == -1: # 此處邏輯較複雜，簡化為標準區間傳遞
                pass

        # 重新實作正確的範圍推導 (Standard Interval Propagation)
        L = [float('-inf')] * n
        R = [float('inf')] * n
        for i in range(n):
            if nums[i] != -1:
                L[i] = R[i] = nums[i]

        # 前向傳遞
        for i in range(1, n):
            if L[i-1] != float('-inf'):
                L[i] = max(L[i], L[i-1] - k)
                R[i] = min(R[i], R[i-1] + k)
        # 後向傳遞
        for i in range(n-2, -1, -1):
            if L[i+1] != float('-inf'):
                L[i] = max(L[i], L[i+1] - k)
                R[i] = min(R[i], R[i+1] + k)

        # 檢查是否有任何位置矛盾
        for i in range(n):
            if L[i] > R[i]: return False

        # 最後核心：我們只能選兩個數 x, y。
        # 這意味著所有滿足 L[i] <= val <= R[i] 的位置，其取值集合的聯集大小必須 <= 2
        # 但題目要求的是「選一個對 (x, y) 並替換每個 -1」。
        # 最優情況是所有 -1 都填入同一個數（即 x=y），或者填入兩個數。
        # 如果存在任何 i 使得 R[i] == L[i]，則該位置必須是那個數。
        fixed_points = set()
        for i in range(n):
            if nums[i] != -1:
                fixed_points.add(nums[i])
            elif L[i] == R[i]:
                fixed_points.add(L[i])

        if len(fixed_points) > 2: return False

        # 如果固定點少於 2 個，我們可以隨便選兩個數填入合法的區間內
        return True

    # 二分搜尋範圍
    low = 0
    high = 10**9
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

