def minDifference(nums: List[int]):
    def check(k):
        L = [float('-inf')] * len(nums)
        R = [float('inf')] * len(nums)
        for i, v in enumerate(nums):
            if v != -1: L[i] = R[i] = v

        for i in range(1, len(nums)):
            if L[i-1] != float('-inf'):
                L[i] = max(L[i], L[i-1] - k)
                R[i] = min(R[i], R[i-1] + k)
        for i in range(len(nums)-2, -1, -1):
            if L[i+1] != float('-inf'):
                L[i] = max(L[i], L[i+1] - k)
                R[i] = min(R[i], R[i+1] + k)

        for i in range(len(nums)):
            if L[i] > R[i]: return False

        # 關鍵：所有必須被滿足的點（固定值或範圍縮減到一個點）不能超過 2 個不同數值
        fixed = set()
        for i, v in enumerate(nums):
            if v != -1: fixed.add(v)
            elif L[i] == R[i]: fixed.add(L[i])
        return len(fixed) <= 2

    low, high = 0, 10**9
    res = high
    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            res = mid
            high = mid - 1
        else:
            low = mid + 1
    return res
