from typing import List

def sortMatrix(grid: List[List[int]]) -> List[List[int]]:
    n = len(grid)
    # Diagonals are identified by (r - c)
    # Bottom-left triangle (including middle): r - c >= 0
    # Top-right triangle: r - c < 0

    diags = {}
    for r in range(n):
        for c in range(n):
            d_id = r - c
            if d_id not in diags:
                diags[d_id] = []
            diags[d_id].append((r, c))

    for d_id, coords in diags.items():
        values = [grid[r][c] for r, c in coords]
        if d_id >= 0:
            # Non-increasing order
            values.sort(reverse=True)
        else:
            # Non-decreasing order
            values.sort()

        for i in range(len(coords)):
            r, c = coords[i]
            grid[r][c] = values[i]

    return grid
