def maxAmount(initialCurrency: str, pairs1: List[List[str]], rates1: List[float], 
               pairs2: List[List[str]], rates2: List[float]) -> float:
    def get_max_rates(start_node, pairs, rates):
        dist = {start_node: 1.0}
        adj = {}
        for p, r in zip(pairs, rates):
            u, v = p
            adj.setdefault(u, {})[v] = max(adj.get(u, {}).get(v, 0), r)
            adj.setdefault(v, {})[u] = max(adj.get(v, {}).get(u, 0), 1.0 / r)

        # Bellman-Ford style or simple BFS/DFS since no positive cycles (max path)
        # Given constraints are small, use Dijkstra-like approach for max path
        queue = [start_node]
        while queue:
            u = queue.pop(0)
            if u in adj:
                for v, r in adj[u].items():
                    if dist.get(v, 0) < dist[u] * r:
                        dist[v] = dist[u] * r
                        queue.append(v)
        return dist

    # Day 1 results
    day1_max = get_max_rates(initialCurrency, pairs1, rates1)

    ans = day1_max.get(initialCurrency, 1.0)

    # Try every possible currency reached on Day 1 as a starting point for Day 2
    for curr, amount in day1_max.items():
        day2_max = get_max_rates(curr, pairs2, rates2)
        ans = max(ans, amount * day2_max.get(initialCurrency, 0.0))

    return float(ans)
