```python
from typing import List

def maxAmount(initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
    def get_max_rates(start_node, pairs, rates):
        adj = {}
        for (u, v), r in zip(pairs, rates):
            if u not in adj: adj[u] = []
            adj[u].append((v, r))
            if v not in adj: adj[v] = []
            adj[v].append((u, 1.0 / r))

        max_r = {start_node: 1.0}
        stack = [start_node]
        while stack:
            u = stack.pop()
            for v, r in adj.get(u, []):
                if max_r[u] * r > max_r.get(v, 0.0):
                    max_r[v] = max_r[u] * r
                    stack.append(v)
        return max_r

    # Get all possible amounts of currencies after Day 1
    day1_results = get_max_rates(initialCurrency, pairs1, rates1)

    # For every currency reached on Day 1, we can perform conversions on Day 2
    # To maximize initialCurrency at the end, we need to find max(day1_res[curr] * day2_res[curr][initialCurrency])
    # This is equivalent to finding the max path in a graph where edges are combined.

    # Step 1: Find max conversion rates for Day 2 starting from every currency back to initialCurrency
    # Wait, it's simpler: For each currency 'c', find the max rate from 'c' to 'initialCurrency' on Day 2.
    # To do this efficiently, we can run a multi-source BFS/DFS or just reverse the graph for Day 2.

    adj2 = {}
    for (u, v), r in zip(pairs2, rates2):
        if u not in adj2: adj2[u] = []
        adj2[u].append((v, r))
        if v not in adj2: adj2[v] = []
        adj2[v].append((u, 1.0 / r))

    # We want to know for each currency 'c', what is the max rate to get back to initialCurrency?
    # Let's run a search starting from initialCurrency on the REVERSED Day 2 graph.
    rev_adj2 = {}
    for (u, v), r in zip(pairs2, rates2):
        if v not in rev_adj2: rev_adj2[v] = []
        rev_adj2[v].append((u, r))
        if u not in rev_adj2: rev_adj2[u] = []
        rev_adj2[u].append((v, 1.0 / r))

    day2_back = {initialCurrency: 1.0}
    stack = [initialCurrency]
    while stack:
        curr = stack.pop()
        for neighbor, r in rev_adj2.get(curr, []):
            if day2_back[curr] * r > day2_back.get(neighbor, 0.0):
                day2_back[neighbor] = day2_back[curr] * r
                stack.append(neighbor)

    ans = 1.0
    for curr, amount in day1_results.items():
        if curr in day2_back:
            ans = max(ans, amount * day2_back[curr])

    return float(ans)
